#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main(void) {
    int N;
    scanf("%d", &N);

    char P[100005];
    scanf("%s", P);

    if (N < 2) {
        printf("*\n");
        return 0;
    }

    int divs[256];
    int dc = 0;

    for (int i = 1; i * i <= N; i++) {
        if (N % i == 0) {
            if (i < N) divs[dc++] = i;
            int j = N / i;
            if (j != i && j < N) divs[dc++] = j;
        }
    }

    qsort(divs, dc, sizeof(int), cmp);

    int cnt[26], tmp[26];

    for (int d = 0; d < dc; d++) {
        int L = divs[d];
        int k = N / L;

        memset(cnt, 0, sizeof(cnt));
        for (int i = 0; i < L; i++) {
            cnt[P[i] - 'a']++;
        }

        int ok = 1;
        for (int b = 1; b < k; b++) {
            memset(tmp, 0, sizeof(tmp));
            int start = b * L;
            int end = start + L;

            for (int i = start; i < end; i++) {
                tmp[P[i] - 'a']++;
            }

            for (int c = 0; c < 26; c++) {
                if (cnt[c] != tmp[c]) {
                    ok = 0;
                    break;
                }
            }

            if (!ok) break;
        }

        if (ok) {
            printf("%.*s\n", L, P);
            return 0;
        }
    }

    printf("*\n");
    return 0;
}
